async function ghRun(fn){if(ghBusy)return;ghBusy=true;['ghSave','ghLoad','ghList','ghClose','ghOwner','ghRepo','ghBranch','ghPath','ghToken','ghFiles','ghConsent'].forEach(id=>$(id).disabled=true);$('ghStatus').textContent='GitHub 요청 중…';try{await fn();}catch(e){$('ghStatus').textContent=e.message;}finally{ghBusy=false;['ghSave','ghLoad','ghList','ghClose','ghOwner','ghRepo','ghBranch','ghPath','ghToken','ghFiles','ghConsent'].forEach(id=>$(id).disabled=false);}}
