$('ghSave').onclick=()=>ghRun(async()=>{if(!$('ghToken').value.trim())throw Error('저장하려면 이 저장소의 Contents 쓰기 권한 토큰이 필요합니다.');if(!$('ghConsent').checked)throw Error('도면 공개 범위를 확인하고 확인란을 선택하세요.');const s=ghSettings(),current=await api(s.url+'?ref='+encodeURIComponent(s.branch),{allow404:true});if(current&&current.type!=='file')throw Error('파일 경로를 확인하세요.');const expected=known.get(s.key);if(expected&&current?.sha!==expected)throw Error('다른 사용자가 이 도면을 변경했습니다. 최신 도면을 다시 열고 병합하세요.');if(current&&!expected&&!confirm('동일 이름의 GitHub 도면이 있습니다. 현재 도면으로 덮어쓸까요? 이전 버전은 GitHub 커밋 기록에 남습니다.')){ $('ghStatus').textContent='저장을 취소했습니다.';return;}
 const serialized=JSON.stringify(layout,null,2);if(new TextEncoder().encode(serialized).length>950000)throw Error('GitHub 직접 저장은 도면 950KB까지 지원합니다. JSON으로 내보내 보관하세요.');const body={message:`layout: ${layout.projectName}`,branch:s.branch,content:utf8base64(serialized)};if(current)body.sha=current.sha;const result=await api(s.url,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});known.set(s.key,result.content.sha);$('ghStatus').textContent=`커밋 완료: ${result.commit.sha.slice(0,7)} · ${s.path}`;$('saveState').textContent=`GitHub 저장 완료 · ${result.commit.sha.slice(0,7)}`;try{localStorage.setItem('warehouse-city-github',JSON.stringify({owner:s.owner,repo:s.repo,branch:s.branch,path:s.path}));}catch{}toast('GitHub 도면 저장 완료');});
$('ghList').onclick=()=>ghRun(async()=>{const s=ghSettings(),base=`https://api.github.com/repos/${encodeURIComponent(s.owner)}/${encodeURIComponent(s.repo)}/contents/layouts?ref=${encodeURIComponent(s.branch)}`,items=await api(base,{allow404:true});$('ghFiles').replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='도면을 선택하세요';$('ghFiles').append(placeholder);for(const f of Array.isArray(items)?items:[]){if(f.type==='file'&&f.name.endsWith('.json')&&f.name!=='index.json'){const opt=document.createElement('option');opt.value=f.path;opt.textContent=f.name;$('ghFiles').append(opt);}}$('ghStatus').textContent=`도면 ${$('ghFiles').options.length-1}개. 목록은 layouts 바로 아래 파일을 표시합니다.`;});
$('ghBackup').onclick=exportJSON;
$('ghCompare').onclick=()=>ghRun(async()=>{const settings=ghSettings(),file=await api(settings.url+'?ref='+encodeURIComponent(settings.branch));const remote=normalize(JSON.parse(fromBase64(file.content))),diff=compareLayouts(layout,remote);$('ghStatus').textContent=`최신 SHA ${file.sha.slice(0,7)} · 로컬에만 ${diff.localOnly.length}개 / 원격에만 ${diff.remoteOnly.length}개 / 수정 ${diff.changed.length}개. 이름 변경 ${diff.projectChanged?'있음':'없음'}, 창고 규격 변경 ${diff.warehouseChanged?'있음':'없음'}. 로컬 JSON을 백업한 뒤 최신 도면을 여세요. 자동 덮어쓰지 않습니다.`;});
$('ghFiles').onchange=()=>{if($('ghFiles').value)$('ghPath').value=$('ghFiles').value;};
$('ghLoad').onclick=()=>ghRun(async()=>{const s=ghSettings(),file=await api(s.url+'?ref='+encodeURIComponent(s.branch));if(file.size>5_000_000||file.encoding!=='base64')throw Error('지원하지 않는 파일 크기 또는 형식입니다.');const next=normalize(JSON.parse(fromBase64(file.content)));if(confirm('GitHub 도면으로 현재 화면을 바꿀까요?')){replace(next);known.set(s.key,file.sha);$('ghStatus').textContent='도면을 불러왔습니다. 기존 브라우저 도면은 실행 취소로 복구할 수 있습니다.';}});
$('leftToggle').onclick=()=>{$('right').classList.remove('open');$('left').classList.toggle('open');};$('rightToggle').onclick=()=>{$('left').classList.remove('open');$('right').classList.toggle('open');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).classList.remove('open'));

function makeLabel(text,x,y,z){
 const c=document.createElement('canvas');c.width=512;c.height=96;
 const ctx=c.getContext('2d');ctx.fillStyle='#143448e6';ctx.fillRect(0,0,512,96);
 ctx.fillStyle='#ffffff';ctx.font='bold 34px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text.slice(0,25),256,48,484);
 const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;const material=new THREE.SpriteMaterial({map:texture,transparent:true,depthTest:false});
 const sprite=new THREE.Sprite(material);sprite.position.set(x,y,z);sprite.scale.set(2.8,.525,1);labelRoot.add(sprite);
}
function buildShell(){
 shellRoot.traverse(m=>{if(m.userData.ownedMaterial)m.material.dispose();});shellRoot.clear();labelRoot.traverse(o=>{if(o.material){o.material.map?.dispose();o.material.dispose();}});labelRoot.clear();
 const w=layout.warehouse;
 for(const z of [-.1,w.depth+.1])box(shellRoot,w.width+.4,w.height,.18,w.width/2,w.height/2,z,'#d4e0e4');
 for(const x of [-.1,w.width+.1])box(shellRoot,.18,w.height,w.depth,x,w.height/2,w.depth/2,'#d4e0e4');
 box(shellRoot,w.width+.4,.16,w.depth+.4,w.width/2,w.height+.2,w.depth/2,'#dce7e8');
 for(let x=2;x<w.width;x+=6){box(shellRoot,.14,.22,w.depth,x,w.height-.2,w.depth/2,'#5e7e8c');const fixture=box(shellRoot,1.6,.05,.28,x,w.height-.36,w.depth/2,'#ffffff');fixture.material=new THREE.MeshStandardMaterial({color:0xffffff,emissive:0xfff8eb,emissiveIntensity:2});fixture.userData.ownedMaterial=true;
 if(shellRoot.children.filter(c=>c.isLight).length<4){const light=new THREE.PointLight(0xfff5e6,70,Math.max(w.width,w.depth),2);light.position.set(x,w.height-.7,w.depth/2);shellRoot.add(light);}
 for(const z of [-.12,w.depth+.12])box(shellRoot,.22,w.height,.22,x,w.height/2,z,'#83949d');}
 shellRoot.visible=mode==='walk';labelRoot.visible=mode!=='walk';
 layout.objects.filter(o=>['rack','dock','office'].includes(o.type)).slice(0,60).forEach(o=>makeLabel(o.name,o.x,o.z+o.height+.8,o.y));
}
