let backgroundImage=null,backgroundData='',backgroundPoints=[];
$('backgroundBtn').onclick=()=>$('backgroundFile').click();
$('backgroundFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg'].includes(file.type)||file.size>5000000)throw Error('PNG/JPEG 5MB 이하를 선택하세요.');const bitmap=await createImageBitmap(file),c=document.createElement('canvas'),ratio=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*ratio);c.height=Math.round(bitmap.height*ratio);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();backgroundData=c.toDataURL('image/jpeg',.8);if(backgroundData.length>900000)throw Error('압축 후 배경이 너무 큽니다. 더 작은 이미지를 선택하세요.');backgroundImage=c;backgroundPoints=[];const preview=$('backgroundCanvas');preview.width=c.width;preview.height=c.height;preview.getContext('2d').drawImage(c,0,0);$('backgroundDialog').showModal();}catch(err){toast(err.message);}e.target.value='';};
$('backgroundCanvas').onclick=e=>{if(backgroundPoints.length===2)backgroundPoints=[];const c=e.currentTarget,r=c.getBoundingClientRect();backgroundPoints.push({x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height});const ctx=c.getContext('2d');ctx.drawImage(backgroundImage,0,0);for(const p of backgroundPoints){ctx.beginPath();ctx.arc(p.x,p.y,8,0,Math.PI*2);ctx.fillStyle='#ee503b';ctx.fill();}};
$('backgroundApply').onclick=()=>{try{const scale=calibrateBackground(backgroundPoints,Number($('backgroundDistance').value),backgroundImage.width,backgroundImage.height);layout.background={...scale,data:backgroundData,x:layout.warehouse.width/2,y:layout.warehouse.depth/2,opacity:.4,locked:true};commit();$('backgroundDialog').close();}catch(e){toast(e.message);}};
$('backgroundClose').onclick=()=>$('backgroundDialog').close();
$('backgroundOpacity').onchange=()=>{if(layout.background){layout.background.opacity=Number($('backgroundOpacity').value);commit();}};
$('backgroundLocked').onchange=()=>{if(layout.background){layout.background.locked=$('backgroundLocked').checked;commit();}};
$('backgroundPosition').onclick=()=>{if(!layout.background||layout.background.locked){toast('배경 잠금을 해제하세요.');return;}const x=Number($('backgroundX').value),y=Number($('backgroundY').value);if(Number.isFinite(x)&&Number.isFinite(y)){layout.background.x=x;layout.background.y=y;commit();}};
$('multiAll').onclick=()=>{multiSelected.clear();layout.objects.filter(o=>!o.locked&&!['aisle','safety','waypoint'].includes(o.type)).forEach(o=>multiSelected.add(o.id));$('multiCount').textContent=multiSelected.size+'개 선택';};
