function batchEdit(action){if(mode!=='edit')return;const next=copy(layout),objects=next.objects.filter(o=>multiSelected.has(o.id));if(!objects.length)return;if(objects.some(o=>o.locked)){toast('잠긴 설비가 포함되어 있습니다.');return;}const dx=Number($('multiX').value),dy=Number($('multiY').value);if(![dx,dy].every(Number.isFinite))return;
 if(action==='move')objects.forEach(o=>{o.x+=dx;o.y+=dy;});
 if(action==='alignX')objects.forEach(o=>o.x=objects[0].x);
 if(action==='alignY')objects.forEach(o=>o.y=objects[0].y);
 if(action==='spaceX'&&objects.length>2){objects.sort((a,b)=>a.x-b.x);const start=objects[0].x,end=objects.at(-1).x;objects.forEach((o,i)=>o.x=start+(end-start)*i/(objects.length-1));}
 if(action==='duplicate'){if(next.objects.length+objects.length>MAX_OBJECTS){toast('설비 수 예산 초과');return;}next.objects.push(...objects.map(o=>({...copy(o),id:uid(),x:o.x+dx,y:o.y+dy})));}
 if(action==='delete')next.objects=next.objects.filter(o=>!multiSelected.has(o.id));
 const error=next.objects.find(o=>placementError(o,next));if(error){toast(error.name+' · '+placementError(error,next)+' · 전체 작업을 취소했습니다.');return;}replace(next);multiSelected.clear();$('multiCount').textContent='선택 해제';}
document.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>batchEdit(b.dataset.batch));
